    await page.goto('/');

    await expect(page.getByTestId('person-row-1').getByTestId('concept-pitch')).toHaveText('254');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-pitch')).toHaveText('221');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-pitch')).toHaveText('390');
    await expect(page.getByTestId('person-row-4').getByTestId('concept-pitch')).toHaveText('140');
    await expect(page.getByTestId('person-row-5').getByTestId('concept-pitch')).toHaveText('42');
    await expect(page.getByTestId('person-row-6').getByTestId('concept-pitch')).toHaveText('96');
    await expect(page.getByTestId('person-row-9').getByTestId('concept-pitch')).toHaveText('199');
  });
});
